INSERT INTO templates (id, builtin, created_by, created_at) VALUES ('ethics-intake', 1, NULL, CAST(strftime('%s', 'now') AS INTEGER) * 1000) ON CONFLICT DO NOTHING;
INSERT INTO template_versions (template_id, version, name, short_name, state, definition, created_by, created_at, published_at, published_by, changes, retired_at) VALUES ('ethics-intake', 1, 'Intake and initial assessment', 'intake', 'published', '{"schemaVersion":1,"id":"ethics-intake","version":1,"name":"Intake and initial assessment","shortName":"intake","description":"A first review of a complaint: is it in scope, and is it worth investigating.","caseReferenceLabel":"Integrity Line reference","numbering":[{"style":"letters","letterCase":"upper","suffix":"."},{"style":"arabic","suffix":"."}],"roles":[{"id":"authors","name":"Authors","kind":"drafting","view":"full","permissions":["edit","share","publish","manage_people","comment_drafts","reply","write_conclusion"]},{"id":"committee","name":"Committee","kind":"reviewing","view":"redacted","permissions":["comment","vote"],"approval":{"kind":"all"}}],"sections":[{"id":"case-details","title":"Case details","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"case-reference","label":"Case reference","requirement":"required","type":"case_value","field":"reference"},{"id":"received-date","label":"Date the project received the case","requirement":"required","type":"date","precision":"day"},{"id":"investigator","label":"Investigator","requirement":"required","type":"text"},{"id":"intake-date","label":"Date of this intake","requirement":"required","type":"date","precision":"day"},{"id":"linked-cases","label":"Linked cases","requirement":"optional","instruction":"Write \"not applicable\" if there are none.","type":"text"},{"id":"linked-reason","label":"Reason for linking the cases","requirement":"optional","instruction":"Write \"not applicable\" if there are no linked cases.","type":"text"},{"id":"complainant-kind","label":"Complainant","requirement":"required","type":"select","multiple":true,"options":[{"id":"known","label":"Known"},{"id":"anonymous","label":"Anonymous"}]},{"id":"complainant","label":"Complainant, if known","requirement":"optional","type":"people","multiple":false},{"id":"subjects","label":"Subject or subjects, if known","requirement":"optional","type":"people","multiple":true},{"id":"reporting-mechanism","label":"How the complaint was reported","requirement":"required","type":"text"}],"sections":[]},{"id":"summary","title":"Summary of the complaint","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"summary-text","label":"Summary","requirement":"required","instruction":"A short account of the complaint.","type":"rich_text"}],"sections":[]},{"id":"allegations","title":"Allegations and regulatory framework","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"allegation-list","label":"Allegations","requirement":"required","type":"repeated","entryLabel":"Allegation","min":1,"items":[{"id":"allegation-type","label":"Type of allegation","requirement":"required","instruction":"For example abuse of power or harassment.","type":"text"},{"id":"allegation-framework","label":"Regulatory framework","requirement":"required","instruction":"The staff regulations, rules, policies and procedures that applied when the incident happened.","type":"rich_text"}]}],"sections":[]},{"id":"jurisdiction-materiality","title":"Jurisdiction and materiality","instruction":"If the answer to either question is no, record why, refer the matter to the behaviour lead and the case manager, and do not complete the remaining parts.","requirement":"required","frontMatter":false,"numbered":true,"items":[],"sections":[{"id":"jurisdiction","title":"Jurisdiction","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"jurisdiction-answer","label":"Does the operational centre have jurisdiction over the subject?","requirement":"required","instruction":"Consider special cases: people who are not staff, staff of other organisations in the programme, locally hired partners, people with a special link to the organisation, and people not on assignment when the incident happened.","type":"select","multiple":false,"options":[{"id":"yes","label":"Yes"},{"id":"no","label":"No"}],"endOptionId":"no"},{"id":"jurisdiction-explanation","label":"Answer and explain","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"materiality","title":"Materiality","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"materiality-answer","label":"If proven, would the allegations be misconduct, and more than an oversight?","requirement":"required","instruction":"Oversight, negligence or incompetence without bad faith, undue benefit or concealment is not enough. For an old case, ask whether it was a breach at the time.","type":"select","multiple":false,"options":[{"id":"yes","label":"Yes"},{"id":"no","label":"No"}],"endOptionId":"no"},{"id":"materiality-explanation","label":"Answer and explain","requirement":"required","type":"rich_text"}],"sections":[]}]},{"id":"witnesses","title":"Potential witnesses","instruction":"Only if the final case strategy needs witnesses. Identify them together with the diversity, equity and inclusion team, who collected the original testimony.","requirement":"optional","frontMatter":false,"numbered":true,"items":[{"id":"witness-list","label":"Witnesses","requirement":"optional","type":"repeated","entryLabel":"Witness","min":0,"items":[{"id":"witness-person","label":"Witness","requirement":"required","type":"people","multiple":false},{"id":"witness-role","label":"Role or connection","requirement":"optional","type":"text"}]}],"sections":[]},{"id":"results","title":"Result of research and further inquiries","instruction":"Describe the information and evidence collected. This part plays the role of the facts in an investigation report.","requirement":"required","frontMatter":false,"numbered":true,"items":[],"sections":[{"id":"research-results","title":"Research results","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"research-results-text","label":"Facts","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"related-cases","title":"Related cases","requirement":"optional","frontMatter":false,"numbered":false,"items":[{"id":"related-cases-text","label":"Cross-referenced or otherwise relevant cases","requirement":"required","instruction":"The subject’s involvement in other cases, at the same or another location.","type":"rich_text"}],"sections":[]},{"id":"other-background","title":"Other relevant background","requirement":"optional","frontMatter":false,"numbered":false,"items":[{"id":"other-background-text","label":"Background","requirement":"required","type":"rich_text"}],"sections":[]}]},{"id":"context-risks","title":"Context and risks","instruction":"Complete a subsection only if it is relevant.","requirement":"optional","frontMatter":false,"numbered":false,"items":[],"sections":[{"id":"evidence-risk","title":"Loss or destruction of evidence","requirement":"optional_with_reason","frontMatter":false,"numbered":false,"items":[{"id":"evidence-risk-text","label":"Loss or destruction of evidence","requirement":"required","instruction":"Is any potential evidence at risk?","type":"rich_text"}],"sections":[]},{"id":"working-environment","title":"Working environment","requirement":"optional_with_reason","frontMatter":false,"numbered":false,"items":[{"id":"working-environment-text","label":"Working environment","requirement":"required","instruction":"Workplace factors, a history of animosity, patterns of similar behaviour.","type":"rich_text"}],"sections":[]},{"id":"cultural-issues","title":"Cultural issues","requirement":"optional_with_reason","frontMatter":false,"numbered":false,"items":[{"id":"cultural-issues-text","label":"Cultural issues","requirement":"required","instruction":"What to consider before a formal investigation, especially in fieldwork and harassment cases.","type":"rich_text"}],"sections":[]},{"id":"logistics-security","title":"Logistical and security issues","requirement":"optional_with_reason","frontMatter":false,"numbered":false,"items":[{"id":"logistics-security-text","label":"Logistical and security issues","requirement":"required","instruction":"Where the people are, site visits, staff safety, and the safety effects of opening an investigation.","type":"rich_text"}],"sections":[]},{"id":"technical-issues","title":"Technical issues","requirement":"optional_with_reason","frontMatter":false,"numbered":false,"items":[{"id":"technical-issues-text","label":"Technical issues","requirement":"required","instruction":"Whether experts are needed, such as digital forensics.","type":"rich_text"}],"sections":[]}]},{"id":"assessment","title":"Case assessment","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"assessment-list","label":"Assessment per allegation","requirement":"required","type":"repeated","entryLabel":"Allegation","min":1,"items":[{"id":"assessment-text","label":"Assessment","requirement":"required","instruction":"Use the same number as in part B, so the parts can be read together. Assess the facts in part E without adding new facts. You may cover credibility, materiality, verifiability and feasibility, and other factors such as priority, proportionality, resources, or alternatives like mediation, coaching or a report to local authorities.","type":"rich_text"}]},{"id":"concluding-statement","label":"Concluding statement","requirement":"required","type":"select","multiple":false,"options":[{"id":"investigate","label":"Investigate: there is sufficient credible evidence"},{"id":"close","label":"Close: the evidence is insufficient or an investigation is unlikely to be conclusive"},{"id":"close-refer","label":"Close and refer to another department"}]},{"id":"assessment-explanation","label":"Explanation of the conclusion","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"recommendation","title":"Recommendation","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"recommendation-list","label":"Recommendation per allegation","requirement":"required","type":"repeated","entryLabel":"Allegation","min":1,"items":[{"id":"recommendation-option","label":"Recommendation","requirement":"required","instruction":"Use the same number as in part B, so the parts can be read together.","type":"select","multiple":false,"options":[{"id":"investigate","label":"Investigate","code":"A"},{"id":"close","label":"Close after the preliminary review","code":"B"},{"id":"close-refer","label":"Close after the review, with a referral and no further action","code":"C"},{"id":"close-refer-feedback","label":"Close after the review, with a referral and a request for feedback","code":"D"},{"id":"refer-more-information","label":"Refer and ask for more information or an assessment","code":"E"},{"id":"merge","label":"Merge with an ongoing case","code":"F"}]},{"id":"recommendation-comment","label":"Comment","requirement":"optional","type":"text"}]}],"sections":[]},{"id":"sign-off","title":"Sign-off","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"sign-investigator","label":"Investigator","requirement":"required","type":"signature"},{"id":"sign-case-manager","label":"Case manager","requirement":"required","type":"signature"}],"sections":[]}],"conclusion":{"id":"committee-conclusion","title":"Behaviour committee conclusion","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"conclusion-date","label":"Date of the committee’s decision","requirement":"required","type":"date","precision":"day"},{"id":"conclusion-members","label":"Members who took part","requirement":"optional","instruction":"Optional: the votes themselves are in the approval record.","type":"rich_text"},{"id":"conclusion-decision","label":"Decision","requirement":"required","type":"rich_text"},{"id":"conclusion-votes","label":"Votes in either direction, if any","requirement":"optional","type":"rich_text"}],"sections":[]},"ending":{"outcomeText":"A screening question ended this review. The matter is referred to the behaviour lead and the case manager, and the remaining parts are not completed.","staysInForce":["sign-off"]},"pageNumbering":"continuous","furniture":{"header":"{title}","footer":"STRICTLY CONFIDENTIAL - page {page}"}}', NULL, CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO templates (id, builtin, created_by, created_at) VALUES ('ethics-investigation', 1, NULL, CAST(strftime('%s', 'now') AS INTEGER) * 1000) ON CONFLICT DO NOTHING;
INSERT INTO template_versions (template_id, version, name, short_name, state, definition, created_by, created_at, published_at, published_by, changes, retired_at) VALUES ('ethics-investigation', 1, 'Investigation report', 'investigation', 'published', '{"schemaVersion":1,"id":"ethics-investigation","version":1,"name":"Investigation report","shortName":"investigation","description":"The report of a full investigation: facts and findings per allegation, conclusion and recommendations.","caseReferenceLabel":"Integrity Line reference","numbering":[{"style":"roman","letterCase":"upper","suffix":"."},{"style":"letters","letterCase":"upper","suffix":"."},{"style":"arabic","suffix":"."},{"style":"letters","letterCase":"lower","suffix":")"}],"roles":[{"id":"authors","name":"Authors","kind":"drafting","view":"full","permissions":["edit","share","publish","manage_people","comment_drafts","reply","write_conclusion"]},{"id":"committee","name":"Committee","kind":"reviewing","view":"redacted","permissions":["comment","vote"],"approval":{"kind":"all"}}],"sections":[{"id":"report-details","title":"Report details","requirement":"required","frontMatter":true,"numbered":false,"items":[{"id":"issue-date","label":"Date of issue","requirement":"required","type":"date","precision":"month"},{"id":"allegations-in-brief","label":"The allegations in brief","requirement":"required","instruction":"Use the organisation’s official categories of abuse and inappropriate behaviour.","type":"text"},{"id":"place","label":"Where it happened","requirement":"required","type":"text"}],"sections":[]},{"id":"executive-summary","title":"Executive summary","instruction":"For long, detailed reports. Keep it short, include only what the report contains, and write it last.","requirement":"optional","frontMatter":true,"numbered":false,"items":[],"sections":[{"id":"summary-findings","title":"Findings","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"summary-findings-text","label":"Findings","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"summary-conclusion","title":"Conclusion","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"summary-conclusion-text","label":"Conclusion","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"summary-individuals","title":"Recommendations for individuals","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"summary-individuals-text","label":"Recommendations for individuals","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"summary-organisational","title":"Organisational and managerial recommendations","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"summary-organisational-text","label":"Organisational and managerial recommendations","requirement":"required","type":"rich_text"}],"sections":[]}]},{"id":"introduction","title":"Introduction","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"introduction-text","label":"Introduction","requirement":"required","instruction":"The chronology that led to the investigation and how it was decided. Keep it short, use real dates, and consider a list or a table.","type":"rich_text"}],"sections":[]},{"id":"scope","title":"Scope, applicable rules and methodology","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"scope-objective","label":"Objective","requirement":"required","instruction":"Name the type of allegation.","type":"rich_text"},{"id":"scope-issues","label":"Issues to establish","requirement":"required","type":"repeated","entryLabel":"Issue","min":1,"items":[{"id":"scope-issue","label":"Issue","requirement":"required","type":"text"}]},{"id":"scope-methods","label":"Methods used","requirement":"required","instruction":"Records, email, computers, site visits, and interviews with the complainant, witnesses and the subject.","type":"rich_text"},{"id":"scope-field-mission","label":"Field mission, with places and dates","requirement":"optional","type":"rich_text"},{"id":"scope-limits","label":"Limits of the scope: what was not investigated","requirement":"optional","type":"rich_text"}],"sections":[]},{"id":"background","title":"Background","instruction":"Add subsections as necessary, each with a title you choose.","requirement":"required","frontMatter":false,"numbered":true,"items":[],"sections":[{"id":"background-topic","title":"Background topic","requirement":"optional","frontMatter":false,"numbered":true,"repeat":{"min":0},"items":[{"id":"background-topic-text","label":"Text","requirement":"required","type":"rich_text"}],"sections":[]}]},{"id":"facts-findings","title":"Facts and findings","instruction":"One subsection per allegation, titled by the allegation, a topic, an event or an investigative activity. In a short report use only Facts or only Findings, but fill at least one.","requirement":"required","frontMatter":false,"numbered":true,"items":[],"sections":[{"id":"allegation-block","title":"Allegation","requirement":"required","frontMatter":false,"numbered":true,"repeat":{"min":1},"items":[],"sections":[{"id":"facts","title":"Facts","requirement":"optional","frontMatter":false,"numbered":true,"items":[{"id":"facts-text","label":"Facts","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"findings","title":"Findings","requirement":"optional","frontMatter":false,"numbered":true,"items":[{"id":"findings-text","label":"Findings","requirement":"required","instruction":"Start from the facts and state what the investigator found, as a paragraph or a list.","type":"rich_text"}],"sections":[]},{"id":"key-element","title":"Key element","instruction":"In a complicated case, split the allegation into its key elements.","requirement":"optional","frontMatter":false,"numbered":true,"repeat":{"min":0},"items":[{"id":"key-element-text","label":"Text","requirement":"required","type":"rich_text"}],"sections":[]}]}]},{"id":"overall-findings","title":"Overall findings","requirement":"optional","frontMatter":false,"numbered":true,"items":[{"id":"overall-findings-text","label":"Overall findings","requirement":"required","instruction":"Findings that cut across allegations, as bullet or numbered points.","type":"rich_text"}],"sections":[]},{"id":"conclusion-statement","title":"Conclusion","requirement":"required","frontMatter":false,"numbered":true,"items":[{"id":"conclusion-text","label":"Conclusion","requirement":"required","instruction":"For each subject, state whether each allegation is substantiated, and list them one per line with a short description.","type":"rich_text"},{"id":"rules-breached","label":"Rules or regulations breached","requirement":"optional","instruction":"Name the law, rule or regulation, with the paragraph.","type":"rich_text"}],"sections":[]},{"id":"recommendation","title":"Recommendation","instruction":"Opening sentence: \"The investigation team recommends that\".","requirement":"required","frontMatter":false,"numbered":true,"items":[],"sections":[{"id":"recommend-individuals","title":"For individuals","requirement":"optional_with_reason","frontMatter":false,"numbered":true,"items":[{"id":"recommend-individuals-text","label":"Recommendation","requirement":"required","type":"rich_text"}],"sections":[]},{"id":"recommend-organisation","title":"Organisational","requirement":"optional_with_reason","frontMatter":false,"numbered":true,"items":[{"id":"recommend-organisation-text","label":"Recommendation","requirement":"required","type":"rich_text"}],"sections":[]}]},{"id":"place-date-signature","title":"Place, date and signature","requirement":"required","frontMatter":false,"numbered":false,"items":[{"id":"prepared-place","label":"Place","requirement":"required","type":"text"},{"id":"prepared-date","label":"Date","requirement":"required","type":"date","precision":"day"},{"id":"investigator-list","label":"Prepared by","requirement":"required","type":"repeated","entryLabel":"Investigator","min":1,"items":[{"id":"investigator-signature","label":"Name and signature","requirement":"required","type":"signature"}]}],"sections":[]},{"id":"interviewees","title":"People interviewed and their codes","requirement":"optional","frontMatter":false,"numbered":false,"items":[{"id":"interviewee-list","label":"People interviewed","requirement":"optional","type":"repeated","entryLabel":"Interviewee","min":0,"items":[{"id":"interviewee-person","label":"Person","requirement":"required","instruction":"The code is the replacement label set in the people list.","type":"people","multiple":false},{"id":"interviewee-position","label":"Position","requirement":"optional","type":"text"}]}],"sections":[]},{"id":"abbreviations","title":"Abbreviations and acronyms","instruction":"Only for complex reports.","requirement":"optional","frontMatter":false,"numbered":false,"items":[{"id":"abbreviation-list","label":"Abbreviations","requirement":"optional","type":"repeated","entryLabel":"Abbreviation","min":0,"items":[{"id":"abbreviation-short","label":"Short form","requirement":"required","type":"text"},{"id":"abbreviation-meaning","label":"Meaning","requirement":"required","type":"text"}]}],"sections":[]},{"id":"exhibits","title":"List of exhibits","instruction":"Exhibits are references; no files are attached.","requirement":"optional","frontMatter":false,"numbered":false,"items":[{"id":"exhibit-list","label":"Exhibits","requirement":"optional","type":"repeated","entryLabel":"Exhibit","min":0,"items":[{"id":"exhibit-type","label":"Type","requirement":"required","type":"select","multiple":false,"options":[{"id":"document","label":"Document"},{"id":"interview-record","label":"Record of an interview"},{"id":"interview-transcript","label":"Transcript of an interview"}]},{"id":"exhibit-from","label":"From","requirement":"required","type":"text"},{"id":"exhibit-to","label":"To","requirement":"optional","type":"text"},{"id":"exhibit-person","label":"Person","requirement":"optional","type":"people","multiple":false},{"id":"exhibit-date","label":"Date","requirement":"required","type":"date","precision":"day"},{"id":"exhibit-subject","label":"Subject","requirement":"required","type":"text"}]}],"sections":[]}],"cover":{"lines":[{"emphasis":"title","parts":[{"kind":"text","text":"Investigation report"}]},{"emphasis":"normal","parts":[{"kind":"case_value","field":"reference"}]},{"emphasis":"normal","parts":[{"kind":"item","itemId":"issue-date"}]},{"emphasis":"subtitle","parts":[{"kind":"item","itemId":"allegations-in-brief"},{"kind":"text","text":"in"},{"kind":"item","itemId":"place"}]}]},"contentsDepth":3,"pageNumbering":"restart_after_front_matter","furniture":{"header":"STRICTLY CONFIDENTIAL - {page} -","footer":"{case}","coverHeader":"STRICTLY CONFIDENTIAL"}}', NULL, CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
